SUBROUTINE INV_TRANSAD(PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, PSPSC3B, PSPSC2, FSPGL_PROC, LDSCDERS, &
  &                    LDVORGP, LDDIVGP, LDUVDER, KPROMA, KVSETUV, KVSETSC, KRESOL, KVSETSC3A, &
  &                    KVSETSC3B, KVSETSC2, PGP, PGPUV, PGP3A, PGP3B, PGP2)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_BOOL, C_PTR, C_LOC, C_NULL_PTR
USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE INV_TRANSAD_CPP_BINDING_SP(ARGS, KSCDERS, KVORGP, KDIVGP, KUVDER, KPROMA, KRESOL, &
  &                                   PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, PSPSC3B, PSPSC2, KVSETUV, &
  &                                   KVSETSC, KVSETSC3A, KVSETSC3B, KVSETSC2, PGP, PGPUV, PGP3A, &
  &                                   PGP3B, PGP2) BIND(C, NAME="inv_transad_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSCDERS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KVORGP
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KDIVGP
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KUVDER
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPVOR(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPDIV(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPSCALAR(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPSC3A(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPSC3B(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPSC2(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETUV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC3A(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC3B(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC2(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGP(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGPUV(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGP3A(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGP3B(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGP2(*)
END SUBROUTINE INV_TRANSAD_CPP_BINDING_SP
SUBROUTINE INV_TRANSAD_CPP_BINDING_DP(ARGS, KSCDERS, KVORGP, KDIVGP, KUVDER, KPROMA, KRESOL, &
  &                                   PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, PSPSC3B, PSPSC2, KVSETUV, &
  &                                   KVSETSC, KVSETSC3A, KVSETSC3B, KVSETSC2, PGP, PGPUV, PGP3A, &
  &                                   PGP3B, PGP2) BIND(C, NAME="inv_transad_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSCDERS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KVORGP
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KDIVGP
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KUVDER
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPVOR(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPDIV(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPSCALAR(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPSC3A(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPSC3B(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPSC2(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETUV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC3A(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC3B(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETSC2(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGP(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGPUV(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGP3A(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGP3B(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGP2(*)
END SUBROUTINE INV_TRANSAD_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPVOR(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPDIV(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPSCALAR(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPSC3A(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPSC3B(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPSC2(:,:)
EXTERNAL                                     FSPGL_PROC
OPTIONAL                                  :: FSPGL_PROC
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSCDERS
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDVORGP
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDDIVGP
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDUVDER
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPROMA
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETUV(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETSC(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETSC3A(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETSC3B(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETSC2(:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGP(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGPUV(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGP3A(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGP3B(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGP2(:,:,:)

TYPE(ARGS_INFO) :: ARGS

! C-interoperable handles for the optional scalar/logical arguments. A null C pointer indicates the
! argument was not present in the Fortran call; otherwise the pointer targets a local temporary.
TYPE(C_PTR) :: KSCDERS_PTR, KVORGP_PTR, KDIVGP_PTR, KUVDER_PTR, KPROMA_PTR, KRESOL_PTR
LOGICAL(KIND=C_BOOL), TARGET :: LSCDERS, LVORGP, LDIVGP, LUVDER
INTEGER(KIND=C_INT),  TARGET :: IPROMA, IRESOL

! NOTE: FSPGL_PROC is a Fourier-space callback that would need to call back into Fortran. It is
! accepted here for interface compatibility but is not yet forwarded to the C++ backend.

ARGS = ARGS_INFO(PSPVOR=PSPVOR, PSPDIV=PSPDIV, PSPSCALAR=PSPSCALAR, PSPSC3A=PSPSC3A, &
  &              PSPSC3B=PSPSC3B, PSPSC2=PSPSC2, KVSETUV=KVSETUV, KVSETSC=KVSETSC, &
  &              KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, KVSETSC2=KVSETSC2, PGP=PGP, &
  &              PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, PGP2=PGP2)

IF (PRESENT(LDSCDERS)) THEN
  LSCDERS = LDSCDERS
  KSCDERS_PTR = C_LOC(LSCDERS)
ELSE
  KSCDERS_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDVORGP)) THEN
  LVORGP = LDVORGP
  KVORGP_PTR = C_LOC(LVORGP)
ELSE
  KVORGP_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDDIVGP)) THEN
  LDIVGP = LDDIVGP
  KDIVGP_PTR = C_LOC(LDIVGP)
ELSE
  KDIVGP_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDUVDER)) THEN
  LUVDER = LDUVDER
  KUVDER_PTR = C_LOC(LUVDER)
ELSE
  KUVDER_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPROMA)) THEN
  IPROMA = KPROMA
  KPROMA_PTR = C_LOC(IPROMA)
ELSE
  KPROMA_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL INV_TRANSAD_CPP_BINDING_SP(ARGS, KSCDERS_PTR, KVORGP_PTR, KDIVGP_PTR, KUVDER_PTR, KPROMA_PTR, &
  &                             KRESOL_PTR, PSPVOR=PSPVOR, PSPDIV=PSPDIV, PSPSCALAR=PSPSCALAR, &
  &                             PSPSC3A=PSPSC3A, PSPSC3B=PSPSC3B, PSPSC2=PSPSC2, KVSETUV=KVSETUV, &
  &                             KVSETSC=KVSETSC, KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, &
  &                             KVSETSC2=KVSETSC2, PGP=PGP, PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, &
  &                             PGP2=PGP2)
#else
CALL INV_TRANSAD_CPP_BINDING_DP(ARGS, KSCDERS_PTR, KVORGP_PTR, KDIVGP_PTR, KUVDER_PTR, KPROMA_PTR, &
  &                             KRESOL_PTR, PSPVOR=PSPVOR, PSPDIV=PSPDIV, PSPSCALAR=PSPSCALAR, &
  &                             PSPSC3A=PSPSC3A, PSPSC3B=PSPSC3B, PSPSC2=PSPSC2, KVSETUV=KVSETUV, &
  &                             KVSETSC=KVSETSC, KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, &
  &                             KVSETSC2=KVSETSC2, PGP=PGP, PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, &
  &                             PGP2=PGP2)
#endif

END SUBROUTINE INV_TRANSAD
